"""JSON-backed todo storage."""

import json
import os


class TodoStore:
    """Persists todos to a JSON file.

    Each todo is a dict: {"id": int, "text": str, "done": bool}.
    Ids auto-increment from 1 and are never reused, even after removal.
    Every mutation is saved to disk immediately.
    """

    def __init__(self, path):
        self.path = path
        self.todos = []
        self._next_id = 1
        if os.path.exists(path):
            with open(self.path, "r", encoding="utf-8") as f:
                data = json.load(f)
            self.todos = data.get("todos", [])
            self._next_id = data.get("next_id", 1)
            if self.todos:
                # Never reuse an id, even if the file was hand-edited.
                self._next_id = max(self._next_id, max(t["id"] for t in self.todos) + 1)

    def _save(self):
        with open(self.path, "w", encoding="utf-8") as f:
            json.dump({"todos": self.todos, "next_id": self._next_id}, f, indent=2)

    def add(self, text):
        """Append a new todo, persist, and return its id."""
        todo = {"id": self._next_id, "text": text, "done": False}
        self.todos.append(todo)
        self._next_id += 1
        self._save()
        return todo["id"]

    def list(self, include_done=True):
        """Return todos in insertion order (all, or only open ones)."""
        if include_done:
            return list(self.todos)
        return [t for t in self.todos if not t["done"]]

    def complete(self, todo_id):
        """Mark a todo done and persist; return False if no such id."""
        for todo in self.todos:
            if todo["id"] == todo_id:
                todo["done"] = True
                self._save()
                return True
        return False

    def remove(self, todo_id):
        """Delete a todo and persist; return False if no such id."""
        for i, todo in enumerate(self.todos):
            if todo["id"] == todo_id:
                del self.todos[i]
                self._save()
                return True
        return False

