"""Persistence layer for the todo CLI.

Todos are stored in a JSON file as:

    {"todos": [{"id": 1, "text": "...", "done": false}, ...], "next_id": N}

``next_id`` is the next id to hand out; it only ever increases, so ids are
never reused even after a todo is removed.
"""

import json
import os


class TodoStore:
    def __init__(self, path):
        self.path = path
        self.todos = []
        self._next_id = 1
        if os.path.exists(path):
            try:
                with open(self.path, "r", encoding="utf-8") as f:
                    content = f.read().strip()
            except OSError:
                content = ""
            if content:
                data = json.loads(content)
                if isinstance(data, dict):
                    self.todos = data.get("todos", [])
                    self._next_id = data.get("next_id", 1)
                else:
                    # Tolerate a bare JSON list of todos.
                    self.todos = data
                if self.todos:
                    self._next_id = max(
                        self._next_id, max(t["id"] for t in self.todos) + 1
                    )

    def _save(self):
        with open(self.path, "w", encoding="utf-8") as f:
            json.dump({"todos": self.todos, "next_id": self._next_id}, f, indent=2)
            f.write("\n")

    def add(self, text):
        """Append a new todo, persist, and return its id."""
        todo = {"id": self._next_id, "text": text, "done": False}
        self.todos.append(todo)
        self._next_id += 1
        self._save()
        return todo["id"]

    def list(self, include_done=True):
        """Return todos in insertion order (all, or only open ones)."""
        if include_done:
            return list(self.todos)
        return [t for t in self.todos if not t["done"]]

    def complete(self, todo_id):
        """Mark a todo done and persist; return False if no such id."""
        for todo in self.todos:
            if todo["id"] == todo_id:
                todo["done"] = True
                self._save()
                return True
        return False

    def remove(self, todo_id):
        """Delete a todo and persist; return False if no such id."""
        for i, todo in enumerate(self.todos):
            if todo["id"] == todo_id:
                del self.todos[i]
                self._save()
                return True
        return False
